      "support_status": "SUFFICIENT",
      "rationale": "P002 explicitly identifies delayed collection as a hypothesis rather than an established cause; P001 supplies the discrepancy being explained."
    }
  },
  "signal_basis": {
    "component_id": "C006.signal_basis",
    "value": "Booking-level timelines include collection records, and independent sources are compared for agreement or disagreement about the same handoff. Corroborated timing alone does not establish why a start was late.",
    "scope": "Investigation of collection timing as a possible explanation, preserving the distinction between collection and actual work start.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
